    description: {
      de: "Die Tarnica ist mit 1346 Metern der höchste Gipfel des polnischen Bieszczady-Gebirges. Der Berg zeichnet sich durch seine markante Form und das große Metallkreuz auf seinem Gipfel aus.",
      hu: "A Tarnica 1346 méteres magasságával a lengyel Bieszczady-hegység legmagasabb pontja. A hegyet jellegzetes alakja és a csúcsán álló nagy fémkereszt teszi felismerhetővé.",
      ro: "Tarnica este cel mai înalt vârf din partea poloneză a Munților Bieszczady, având 1346 metri. Muntele se distinge prin forma sa specifică și crucea metalică mare de pe vârf.",
      en: "Tarnica is the highest peak of the Polish Bieszczady Mountains at 1346 meters. The mountain is characterized by its distinctive shape and a large metal cross at the summit.",
      es: "El Tarnica es, con 1346 metros, el pico más alto de las montañas Bieszczady polacas. El monte destaca por su forma distintiva y la gran cruz de metal en su cima.",
      pt: "O Tarnica é, com 1346 metros, o pico mais alto das montanhas Bieszczady polacas. O monte destaca-se pela sua forma distinta e pela grande cruz de metal no seu topo.",
      fr: "Le Tarnica est, avec 1 346 mètres, le point culminant des monts Bieszczady polonais. La montagne se distingue par sa forme caractéristique et la grande croix métallique à son sommet.",
    },
