      ro: ["Depozite mari de gaze naturale și sulf", "Acoperit de nisipuri și depozite glaciare", "Include Pădurea Sandomierz", "Zonă industrială și agricolă importantă"],
      en: ["Large deposits of natural gas and sulfur", "Covered by sands and glacial deposits", "Includes the Sandomierz Primeval Forest", "Important industrial and agricultural region"],
      es: ["Grandes yacimientos de gas natural y azufre", "Cubierto por arenas y depósitos de la edad de hielo", "Incluye el Bosque Primario de Sandomierz", "Importante zona industrial y agrícola"],
      pt: ["Grandes jazidas de gás natural e enxofre", "Coberto por areias e depósitos da idade do gelo", "Inclui a Floresta de Sandomierz", "Importante área industrial e agrícola"],
      fr: ["Importants gisements de gaz naturel et de soufre", "Recouvert de sables et de dépôts glaciaires", "Comprend l'ancienne forêt de Sandomierz", "Zone industrielle et agricole importante"],
