      es: ["La altura de la duna varía entre 30 y 42 metros según el viento", "El viento predominante empuja la masa de arena de 3 a 10 metros al este cada año", "El área forma parte de la Reserva de la Biosfera de la UNESCO desde 1977", "Las dunas errantes cubren más de 500 hectáreas en el parque nacional", "La fina arena de cuarzo emite un chirrido característico al caminar sobre ella", "Bajo la arena aparecen a menudo restos de bosques enterrados hace siglos", "Desde la cima se puede ver simultáneamente el Mar Báltico y el lago Łebsko"],
      pt: ["A altura da duna varia entre 30 e 42 metros, dependendo das condições do vento", "O vento predominante empurra a massa de areia de 3 a 10 metros para leste anualmente", "A área faz parte da Reserva da Biosfera da UNESCO desde 1977", "As dunas móveis cobrem uma área de mais de 500 hectares no parque nacional", "A areia fina de quartzo emite um rangido característico ao caminhar sobre ela", "Sob a areia, surgem frequentemente restos de florestas enterradas há centenas de anos", "Do topo da duna é possível ver simultaneamente o Mar Báltico e o lago Łebsko"],
      fr: ["La hauteur de la dune varie entre 30 et 42 mètres selon les vents", "Le vent dominant déplace la masse de sable de 3 à 10 mètres vers l'est par an", "La zone fait partie d'une réserve de biosphère de l'UNESCO depuis 1977", "Les dunes mobiles couvrent plus de 500 hectares dans le parc national", "Le sable de quartz fin émet un grincement particulier sous les pas", "Sous le sable apparaissent souvent des restes de forêts enfouies il y a des siècles", "Du sommet, on peut voir simultanément la mer Baltique et le lac Łebsko"],
