      de: "Das Hirschberger Tal ist eine große Senke in den Westsudeten am Fuße des Riesengebirges. Es ist berühmt für seine hohe Dichte an historischen Schlössern, Parks und Herrensitzen.",
      hu: "A Jelenia Góra-i-medence egy nagy süllyedék a Nyugati-Szudétákban, az Óriás-hegység lábánál. Híres a történelmi kastélyok, parkok és nemesi kúriák rendkívüli sűrűségéről.",
      ro: "Depresiunea Jelenia Góra este o cavitate mare în Sudeții Occidentali, la poalele Munților Karkonosze. Este faimoasă pentru densitatea mare de castele istorice și parcuri.",
      en: "The Jelenia Góra Valley is a large depression in the Western Sudetes at the foot of the Karkonosze Mountains. It is famous for its high density of historic castles, parks, and manors.",
