      ro: ["Tip: piemont", "Tranziție: câmpie către munți", "Altitudine: până la 300 metri", "Regiune: Silezia Inferioară"],
      en: ["Type: piedmont", "Transition: lowland to mountains", "Elevation: up to 300 meters", "Region: Lower Silesia"],
      es: ["Tipo: Piedemonte", "Transición: Tierras bajas a montaña", "Altitud: hasta 300 metros", "Región: Baja Silesia"],
      pt: ["Tipo: Sopé (Piemonte)", "Transição: Planície para montanha", "Altitude: até 300 metros", "Região: Baixa Silésia"],
      fr: ["Type : Piémont", "Transition : Plaine vers montagne", "Altitude : jusqu'à 300 mètres", "Région : Basse-Silésie"],
