      de: ["Typ: Moränenlandschaft", "Region: Woiwodschaft Lebus", "Besonderheit: zahlreiche Seen", "Topografie: wellig"],
      hu: ["Típus: morénás táj", "Régió: Lubuski vajdaság", "Jellemző: számos tó", "Topográfia: hullámos"],
