      hu: ["A tóhátság legmagasabb pontja a 227 méteres Góra Bukowiecka.", "A terület több mint 50%-át sűrű erdők borítják.", "A Niesłysz-tó a régió legnagyobb tava, területe 486 hektár.", "A Międzyrzeczi Erődített Régió (MRU) folyosóinak hossza meghaladja a 30 km-t.", "A Łagowski Tájvédelmi Körzetet 1985-ben hozták létre.", "A régió tavai Lengyelország legtisztább vizei közé tartoznak."],
      ro: ["Cota maximă de altitudine este de 227 de metri pe dealul Bukowiecka.", "Peste 50% din suprafața regiunii este acoperită de păduri compacte.", "Lacul Niesłysz este cel mai mare din district, având 486 de hectare.", "Sistemul subteran al MRU are o lungime totală de peste 30 km.", "Parcul Peisagistic Łagowski a fost înființat oficial în anul 1985.", "Regiunea este renumită pentru puritatea excepțională a lacurilor sale."],
      en: ["The highest elevation is Góra Bukowiecka at 227 meters.", "More than 50% of the region is covered by dense forests.", "Lake Niesłysz is the largest in the area, covering 486 hectares.", "The underground tunnel system of the MRU is over 30 km long.", "The Łagów Landscape Park was established in 1985.", "The region is known for having some of the cleanest lakes in Poland."],
      es: ["El distrito de los lagos de Lubusz incluye unos 150 lagos", "El lago más grande es el Sławskie con 8,2 kilómetros cuadrados", "La región se extiende sobre 3.000 kilómetros cuadrados", "El Parque Nacional Drawa se encuentra al este del distrito", "El punto más alto alcanza los 150 metros", "El río Óder fluye durante 80 kilómetros a lo largo de la frontera"],
      pt: ["A região dos lagos de Lubusz abrange cerca de 150 lagos", "O maior lago é o Sławskie, com 8,2 quilómetros quadrados", "A região estende-se por mais de 3.000 quilómetros quadrados", "O Parque Nacional Drawa situa-se a leste da região dos lagos", "O ponto mais alto tem 150 metros de altitude", "O rio Óder corre ao longo de 80 quilómetros da fronteira"],
      fr: ["La région des lacs de Lubusz comprend environ 150 lacs", "Le plus grand lac est le Sławskie avec 8,2 kilomètres carrés", "La région s'étend sur 3 000 kilomètres carrés", "Le parc national de Drawa se trouve à l'est de la région des lacs", "Le point culminant est de 150 mètres", "L'Oder coule sur 80 kilomètres le long de la frontière"],
